export const es: Record<string, string> = { ...esBase, ...esC, ...esD, ...esP, ...esE, ...esX };
export const en: Record<string, string> = { ...enA, ...enB, ...enC, ...enD, ...enP, ...enE, ...enX };
export const catalogs: Record<Locale, Record<string, string>> = { es, en };

/** Message for the ACTIVE locale. A missing English id falls back to Spanish (never to a blank); `i18n_coverage.test.ts` fails the build if any id lacks an English entry. A missing id shows the id itself. */
export const t = (id: string): string => (getLocale() === "en" ? en[id] ?? es[id] ?? id : es[id] ?? id);
export const tIn = (locale: Locale, id: string): string => catalogs[locale][id] ?? id;
export const hasMsg = (id: string): boolean => id in (getLocale() === "en" ? en : es);

/** t() with `{name}` placeholders. Unknown placeholders are left visible rather than hidden. */
export const tf = (id: string, vars: Record<string, string | number | null | undefined>): string =>
  t(id).replace(/\{([A-Za-z0-9_]+)\}/g, (m, k: string) => (k in vars && vars[k] !== null && vars[k] !== undefined ? String(vars[k]) : m));

/** Presentation mapping for a backend-supplied enumerated value: `${prefix}.${value}`. The persisted/authoritative value is never altered; an unmapped value is shown AS RECEIVED (never guessed). */
export const tEnum = (prefix: string, value: string | null | undefined): string => {
  if (value === null || value === undefined || value === "") return "—";
  const id = `${prefix}.${value}`;
  return hasMsg(id) ? t(id) : value;
};

/** Presentation-only: the backend stores the fixed Spanish source label of the scripted drill ("Simulación ROJO", alerts.py). That exact template is shown in the active language;
 *  any other label (a name the owner typed, "Fuente 1", a file name) is user data and is shown exactly as stored. Stored values are never changed. */
export const BACKEND_DRILL_SOURCE_LABEL = "Simulación ROJO";
export const sourceLabel = (label: string): string => (label === BACKEND_DRILL_SOURCE_LABEL ? t("mg.xc.sim.drill_source") : label);
